files.game.js:
const cv = document.getElementById('game');
const ctx = cv.getContext('2d');
const W = cv.width, H = cv.height;
const PAD = { w: 80, h: 10, x: W / 2 - 40, y: H - 24 };
const ball = { x: W / 2, y: H - 40, r: 6, vx: 3, vy: -3 };
const BRICK_W = 48, BRICK_H = 16, ROWS = 5, COLS = 10;
let bricks = [];
let left = 0, running = true;
const keys = {};
for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) { bricks.push({ x: c * (BRICK_W + 4) + 8, y: r * (BRICK_H + 4) + 30, alive: true, hue: 120 - r * 20 }); left++; }

addEventListener('keydown', e => { keys[e.key] = true; if (e.key === 'r' || e.key === 'R') { bricks.forEach(b => { b.alive = true; }); left = ROWS * COLS; ball.x = W/2; ball.y = H-40; ball.vx = 3; ball.vy = -3; running = true; } });
addEventListener('keyup', e => { keys[e.key] = false; });

function step() {
  if (keys['ArrowLeft']) PAD.x -= 6;
  if (keys['ArrowRight']) PAD.x += 6;
  PAD.x = Math.max(0, Math.min(W - PAD.w, PAD.x));
  if (!running) return;
  ball.x += ball.vx; ball.y += ball.vy;
  if (ball.x < ball.r || ball.x > W - ball.r) ball.vx *= -1;
  if (ball.y < ball.r) ball.vy *= -1;
  if (ball.y + ball.r > PAD.y && ball.y + ball.r < PAD.y + PAD.h + 6 && ball.x > PAD.x && ball.x < PAD.x + PAD.w) {
    ball.vy = -Math.abs(ball.vy); ball.vx = (ball.x - (PAD.x + PAD.w / 2)) / 12;
  }
  for (const b of bricks) {
    if (!b.alive) continue;
    if (ball.x > b.x && ball.x < b.x + BRICK_W && ball.y > b.y && ball.y < b.y + BRICK_H) {
      b.alive = false; left--; ball.vy *= -1;
    }
  }
  if (ball.y > H) { running = false; }
}

function draw() {
  ctx.fillStyle = '#14161b'; ctx.fillRect(0, 0, W, H);
  for (const b of bricks) { if (!b.alive) continue; ctx.fillStyle = 'hsl(' + b.hue + ', 70%, 55%)'; ctx.fillRect(b.x, b.y, BRICK_W, BRICK_H); }
  ctx.fillStyle = '#f7f5ec'; ctx.fillRect(PAD.x, PAD.y, PAD.w, PAD.h);
  ctx.fillStyle = '#b8f23a'; ctx.beginPath(); ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2); ctx.fill();
}

setInterval(() => {
  step(); draw();
  document.getElementById('score').textContent = left === 0 ? 'You win! Press R to play again.' : (running ? 'Bricks left: ' + left : 'Missed — press R to restart.');
}, 16);
